) OR (QueryName ILIKE '%.rustdesk.com' AND QueryName ILIKE 'rs-%')) AND NOT ((((Image ILIKE 'C:\\Program Files (x86)\\Avant Browser\\%' OR Image ILIKE 'C:\\Program Files\\Avant Browser\\%') AND Image ILIKE '%\\avant.exe') OR (Image ILIKE '%\\brave.exe' AND Image ILIKE 'C:\\Program Files\\BraveSoftware\\%') OR ((Image = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe' OR Image = 'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe')) OR ((Image ILIKE '%\\MsMpEng.exe' OR Image ILIKE '%\\MsSense.exe')) OR ((Image ILIKE 'C:\\Program Files (x86)\\Microsoft\\EdgeWebView\\Application\\%') OR (Image ILIKE '%\\WindowsApps\\MicrosoftEdge.exe') OR ((Image = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe' OR Image = 'C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe'))) OR ((Image ILIKE 'C:\\Program Files (x86)\\Microsoft\\EdgeCore\\%' OR Image ILIKE 'C:\\Program Files\\Microsoft\\EdgeCore\\%') AND (Image ILIKE '%\\msedge.exe' OR Image ILIKE '%\\msedgewebview2.exe')) OR ((Image ILIKE 'C:\\Program Files\\Falkon\\%' OR Image ILIKE 'C:\\Program Files (x86)\\Falkon\\%') AND Image ILIKE '%\\falkon.exe') OR ((Image = 'C:\\Program Files\\Mozilla Firefox\\firefox.exe' OR Image = 'C:\\Program Files (x86)\\Mozilla Firefox\\firefox.exe')) OR (Image ILIKE '%\\AppData\\Local\\Flock\\%' AND Image ILIKE '%\\Flock.exe') OR ((Image = 'C:\\Program Files (x86)\\Internet Explorer\\iexplore.exe' OR Image = 'C:\\Program Files\\Internet Explorer\\iexplore.exe')) OR (Image ILIKE '%\\AppData\\Local\\Maxthon\\%' AND Image ILIKE '%\\maxthon.exe') OR (Image ILIKE '%\\AppData\\Local\\Programs\\midori-ng\\%' AND Image ILIKE '%\\Midori Next Generation.exe') OR (Image ILIKE '%\\AppData\\Local\\Programs\\Opera\\%' AND Image ILIKE '%\\opera.exe') OR (Image ILIKE '%\\AppData\\Local\\Phoebe\\%' AND Image ILIKE '%\\Phoebe.exe') OR (Image ILIKE '%\\safari.exe') OR ((Image ILIKE 'C:\\Program Files\\SeaMonkey\\%' OR Image ILIKE 'C:\\Program Files (x86)\\SeaMonkey